typedef unsigned char uint8;
typedef float rational_t;
typedef float time_value_t;

class beam;

class beam_effect_type {
protected:
    beam_effect_type() {}
    virtual ~beam_effect_type() {}
    virtual void apply_start_vals(beam *the_beam) {}
    virtual void apply_target_vals(beam *the_beam) {}
    virtual void apply_delta_vals(beam *the_beam, time_value_t time) {}
    virtual void reverse() {}
    virtual beam_effect_type *make_instance() { return 0; }
};

class beam_effect_alpha : public beam_effect_type {
protected:
    beam_effect_alpha() {}
    virtual ~beam_effect_alpha() {}
    virtual void apply_start_vals(beam *the_beam);
    virtual void apply_target_vals(beam *the_beam);
    virtual void apply_delta_vals(beam *the_beam, time_value_t time);
    virtual void reverse();

    uint8 start;
    uint8 target;
    rational_t delta;
    rational_t curr;

    virtual beam_effect_type *make_instance();

    friend class beam_effect;
};

class beam_effect {
    enum effect_mode {
        EFFECT_DEAD = 0,
        EFFECT_DELAY = 1,
        EFFECT_ACTIVE = 2,
        EFFECT_INVERTED_DELAY = -1,
        EFFECT_INVERTED_ACTIVE = -2
    };

    beam *my_beam;
    beam_effect_type *effect;
    unsigned short id;
    char mode;
    rational_t timer;
    rational_t loop_delay;
    rational_t duration;

    virtual void dump();
    virtual void set_active();
    virtual void set_delaying();

public:
    virtual ~beam_effect();
    virtual void set_alpha_delta(
        uint8 start_alpha,
        uint8 end_alpha,
        rational_t duration,
        rational_t delay = 0.0f,
        rational_t loop_delay = -1.0f,
        bool invert_loop = false);
};

void *operator new(
    unsigned int size,
    unsigned int flags,
    const char *description,
    int line);

extern const char beam_alpha_description[];

__asm__(".equ __nw__FUiUiPCci, 0x002AC578");
__asm__(".equ beam_alpha_description, 0x004E5DB8");
__asm__(".equ _vt$17beam_effect_alpha, 0x004FCF88");

#define NEW new(0, beam_alpha_description, 0)

void beam_effect::set_alpha_delta(uint8 start_alpha, uint8 end_alpha, rational_t the_duration, rational_t the_delay, rational_t the_loop_delay, bool invert_loop)
{
  dump();

  effect = NEW beam_effect_alpha();
  beam_effect_alpha *alpha_effect = (beam_effect_alpha *)effect;

  alpha_effect->start = start_alpha;
  alpha_effect->target = end_alpha;

  duration = the_duration;

  if(duration > 0)
  {
    alpha_effect->delta = (alpha_effect->target - alpha_effect->start) / duration;
  }

  if(invert_loop)
    mode = EFFECT_INVERTED_DELAY;
  else
    mode = EFFECT_DELAY;

  loop_delay = the_loop_delay;
  timer = the_delay;
}
